
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_x_s12h_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_x_s12h", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.229098100405329e+00, -3.166374279614410e+00, -3.078740323712668e+00, -2.957905433101784e+00, -2.794483252603535e+00, -2.579680018647512e+00, -2.308876537102876e+00, -1.986535272369036e+00, -1.626692818051666e+00, -1.241907306490766e+00, -8.365363582364596e-01, -5.365123834034030e-01, -4.546370755876089e-01, -3.758784262086817e-01, -2.824452635511783e-01, -1.875911488542757e-01, -1.006093035633436e-01, -3.637047012540866e-02, -7.899812286609360e-03, -8.883902351150281e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


